@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=Inter:wght@400;500;600&display=swap');
@import url('https://cdn.jsdelivr.net/npm/remixicon@4.2.0/fonts/remixicon.css');

:root {
  --font-heading: 'Plus Jakarta Sans', sans-serif;
  --font-body: 'Inter', sans-serif;

  --color-black: #000000;
  --color-charcoal: #12141d;
  --color-navy: #0d1b2a;
  --color-white: #ffffff;
  --color-gray-50: #f8f9fa;
  --color-gray-100: #f1f3f5;
  --color-gray-200: #e9ecef;
  --color-gray-600: #868e96;
  --color-gray-800: #343a40;

  --color-green: #55DA9B;
  --color-purple: #5620C1;
  --color-coral: #ff6b6b;
  --color-yellow: #fcc419;

  --radius-sm: 8px;
  --radius-md: 16px;
  --radius-lg: 24px;
  --radius-pill: 999px;

  --shadow-sm: 0 2px 8px rgba(0,0,0,0.05);
  --shadow-md: 0 8px 24px rgba(0,0,0,0.08);
  --shadow-lg: 0 24px 48px rgba(0,0,0,0.12);

  --container-width: 1200px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-body);
  color: var(--color-gray-800);
  background-color: var(--color-white);
  line-height: 1.6;
  overflow-x: hidden;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--color-black);
  line-height: 1.2;
}

a {
  text-decoration: none;
  color: inherit;
}

ul {
  list-style: none;
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

.container {
  max-width: var(--container-width);
  margin: 0 auto;
  padding: 0 24px;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 24px;
  border-radius: var(--radius-pill);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 16px;
  cursor: pointer;
  transition: all 0.2s ease;
  border: none;
}

.btn-primary {
  background-color: var(--color-green);
  color: var(--color-black);
}

.btn-primary:hover {
  background-color: #4ac78d;
  transform: translateY(-2px);
}

.btn-secondary {
  background-color: var(--color-white);
  color: var(--color-black);
  border: 1px solid var(--color-gray-200);
}

.btn-secondary:hover {
  border-color: var(--color-gray-800);
  transform: translateY(-2px);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-white);
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.btn-outline:hover {
  background-color: rgba(255, 255, 255, 0.1);
  border-color: var(--color-white);
}

/* Header */
header {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  padding: 20px 0;
}

.header-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.logo {
  font-family: var(--font-heading);
  font-size: 24px;
  font-weight: 800;
  color: var(--color-white);
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo i {
  color: var(--color-green);
}

.nav-links {
  display: flex;
  gap: 32px;
  align-items: center;
}

.nav-links a {
  color: var(--color-white);
  font-weight: 500;
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--color-green);
}

.header-actions {
  display: flex;
  gap: 16px;
  align-items: center;
}

.header-actions .sign-in {
  color: var(--color-white);
  font-weight: 500;
}

.header-actions .sign-in:hover {
  color: var(--color-green);
}

/* Hero Section */
.hero {
  background-color: var(--color-charcoal);
  padding: 180px 0 80px;
  position: relative;
  overflow: hidden;
  color: var(--color-white);
  text-align: center;
}

.hero-shape {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  z-index: 1;
}

.hero-shape-1 {
  top: -10%;
  left: -5%;
  width: 400px;
  height: 400px;
  background-color: rgba(86, 32, 193, 0.4);
}

.hero-shape-2 {
  bottom: -10%;
  right: -5%;
  width: 500px;
  height: 500px;
  background-color: rgba(85, 218, 155, 0.3);
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  margin: 0 auto;
}

.hero h1 {
  font-size: 64px;
  font-weight: 800;
  color: var(--color-white);
  margin-bottom: 24px;
  letter-spacing: -0.02em;
}

.hero p.subtitle {
  font-size: 24px;
  color: rgba(255, 255, 255, 0.8);
  margin-bottom: 40px;
}

.hero-ctas {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  margin-bottom: 24px;
}

.hero-ctas .btn {
  width: 100%;
  max-width: 320px;
  height: 56px;
  font-size: 18px;
}

.hero-ctas .btn-google {
  background-color: var(--color-white);
  color: var(--color-black);
}

.hero-ctas .btn-google:hover {
  background-color: var(--color-gray-100);
}

.hero-ctas .btn-email {
  background-color: var(--color-purple);
  color: var(--color-white);
}

.hero-ctas .btn-email:hover {
  background-color: #6a2ceb;
}

.hero-legal {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.5);
  max-width: 400px;
  margin: 0 auto;
  line-height: 1.5;
}

/* Category Pills */
.hero-categories {
  position: relative;
  z-index: 2;
  margin-top: 80px;
  padding-bottom: 20px;
}

.categories-scroll {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding: 0 24px;
  scrollbar-width: none;
  -ms-overflow-style: none;
}

.categories-scroll::-webkit-scrollbar {
  display: none;
}

.category-pill {
  background-color: rgba(255, 255, 255, 0.1);
  color: var(--color-white);
  padding: 12px 24px;
  border-radius: var(--radius-pill);
  font-weight: 500;
  white-space: nowrap;
  backdrop-filter: blur(10px);
  transition: all 0.2s;
  cursor: pointer;
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.category-pill:hover {
  background-color: var(--color-green);
  color: var(--color-black);
}

/* Features */
.features {
  padding: 100px 0;
  background-color: var(--color-white);
}

.features-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.feature-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background-color: var(--color-gray-50);
  transition: transform 0.3s ease;
}

.feature-card:hover {
  transform: translateY(-8px);
}

.feature-icon {
  width: 64px;
  height: 64px;
  background-color: rgba(86, 32, 193, 0.1);
  color: var(--color-purple);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 32px;
  margin: 0 auto 24px;
}

.feature-card h3 {
  font-size: 20px;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--color-gray-600);
}

/* Stats */
.stats {
  padding: 80px 0;
  background-color: var(--color-green);
  color: var(--color-black);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item h3 {
  font-size: 64px;
  font-weight: 800;
  margin-bottom: 8px;
}

.stat-item p {
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 18px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  opacity: 0.8;
}

/* Courses Section */
.courses {
  padding: 100px 0;
  background-color: var(--color-gray-50);
}

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: 40px;
  font-weight: 800;
  margin-bottom: 16px;
}

.section-header p {
  font-size: 18px;
  color: var(--color-gray-600);
  max-width: 600px;
  margin: 0 auto;
}

.course-tabs {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-bottom: 24px;
  margin-bottom: 32px;
  scrollbar-width: none;
}

.course-tabs::-webkit-scrollbar {
  display: none;
}

.tab-btn {
  padding: 10px 20px;
  border-radius: var(--radius-pill);
  background-color: var(--color-white);
  border: 1px solid var(--color-gray-200);
  font-family: var(--font-heading);
  font-weight: 600;
  font-size: 14px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.2s;
  color: var(--color-gray-600);
}

.tab-btn:hover {
  border-color: var(--color-gray-800);
  color: var(--color-black);
}

.tab-btn.active {
  background-color: var(--color-black);
  color: var(--color-white);
  border-color: var(--color-black);
}

.courses-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

.course-card {
  background-color: var(--color-white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all 0.3s ease;
  cursor: pointer;
}

.course-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-md);
}

.course-thumb {
  width: 100%;
  height: 180px;
  background-color: var(--color-gray-200);
  position: relative;
}

.course-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.course-duration {
  position: absolute;
  bottom: 12px;
  right: 12px;
  background-color: rgba(0,0,0,0.7);
  color: var(--color-white);
  font-size: 12px;
  padding: 4px 8px;
  border-radius: 4px;
  font-weight: 600;
}

.course-info {
  padding: 20px;
}

.course-title {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.course-instructor {
  font-size: 14px;
  color: var(--color-gray-600);
  margin-bottom: 16px;
}

.course-meta {
  display: flex;
  align-items: center;
  font-size: 13px;
  color: var(--color-gray-600);
  gap: 6px;
}

.course-meta i {
  color: var(--color-purple);
}

/* Creative Feed */
.creative-feed {
  padding: 100px 0;
  background-color: var(--color-white);
}

.feed-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feed-content h2 {
  font-size: 48px;
  font-weight: 800;
  margin-bottom: 40px;
}

.feed-item {
  display: flex;
  gap: 24px;
  margin-bottom: 32px;
}

.feed-item-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  background-color: var(--color-yellow);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
  flex-shrink: 0;
}

.feed-item:nth-child(2) .feed-item-icon { background-color: var(--color-coral); color: white; }
.feed-item:nth-child(3) .feed-item-icon { background-color: var(--color-purple); color: white; }

.feed-item h3 {
  font-size: 20px;
  margin-bottom: 8px;
}

.feed-item p {
  color: var(--color-gray-600);
}

.feed-visual {
  background-color: var(--color-gray-100);
  border-radius: var(--radius-lg);
  padding: 40px;
  position: relative;
}

/* Abstract feed visual placeholder */
.abstract-feed {
  width: 100%;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #f1f3f5 0%, #e9ecef 100%);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-md);
  position: relative;
  overflow: hidden;
}

.abstract-card {
  position: absolute;
  background: white;
  border-radius: 12px;
  padding: 16px;
  box-shadow: var(--shadow-sm);
}

.abstract-card-1 { top: 10%; left: 10%; width: 60%; height: 40%; }
.abstract-card-2 { bottom: 10%; right: 10%; width: 50%; height: 35%; }

/* Teachers Carousel */
.teachers {
  padding: 100px 0;
  background-color: var(--color-charcoal);
  color: var(--color-white);
  overflow: hidden;
}

.teachers .section-header h2 {
  color: var(--color-white);
}

.teachers .section-header p {
  color: rgba(255, 255, 255, 0.7);
}

.teachers-carousel {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  padding: 24px 24px 48px;
  margin: 0 calc(-50vw + 50%);
  scrollbar-width: none;
}

.teachers-carousel::-webkit-scrollbar {
  display: none;
}

.teacher-card {
  min-width: 280px;
  background-color: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  text-align: center;
  transition: transform 0.3s;
}

.teacher-card:hover {
  transform: translateY(-8px);
  background-color: rgba(255,255,255,0.1);
}

.teacher-avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  margin: 0 auto 20px;
  background-color: var(--color-gray-600);
  overflow: hidden;
}

.teacher-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.teacher-name {
  font-size: 20px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--color-white);
}

.teacher-specialty {
  color: var(--color-green);
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

/* Testimonials */
.testimonials {
  padding: 100px 0;
  background-color: var(--color-gray-50);
}

.testimonials-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 32px;
}

.testimonial-card {
  background-color: var(--color-white);
  padding: 32px;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}

.testimonial-stars {
  color: var(--color-yellow);
  margin-bottom: 16px;
  font-size: 20px;
}

.testimonial-quote {
  font-size: 18px;
  font-style: italic;
  margin-bottom: 24px;
  color: var(--color-gray-800);
  line-height: 1.6;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 12px;
}

.author-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: var(--color-gray-200);
}

.author-name {
  font-weight: 700;
  color: var(--color-black);
}

/* Teams */
.teams {
  padding: 100px 0;
  background-color: var(--color-purple);
  color: var(--color-white);
  text-align: center;
}

.teams-inner {
  max-width: 800px;
  margin: 0 auto;
}

.teams h2 {
  font-size: 48px;
  color: var(--color-white);
  margin-bottom: 24px;
}

.teams p {
  font-size: 20px;
  color: rgba(255,255,255,0.9);
  margin-bottom: 40px;
}

.teams .btn {
  background-color: var(--color-white);
  color: var(--color-purple);
}

.teams .btn:hover {
  background-color: var(--color-gray-100);
}

/* FAQ */
.faq {
  padding: 100px 0;
  background-color: var(--color-white);
}

.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--color-gray-200);
}

.faq-question {
  padding: 24px 0;
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  font-family: var(--font-heading);
  font-size: 20px;
  font-weight: 600;
  color: var(--color-black);
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.faq-question i {
  transition: transform 0.3s;
  color: var(--color-purple);
}

.faq-item.active .faq-question i {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease-out;
}

.faq-answer p {
  padding-bottom: 24px;
  color: var(--color-gray-600);
  font-size: 16px;
  line-height: 1.6;
}

/* Footer */
footer {
  background-color: var(--color-black);
  color: var(--color-white);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 64px;
}

.footer-brand .logo {
  margin-bottom: 24px;
}

.footer-brand p {
  color: rgba(255,255,255,0.6);
  font-size: 14px;
  margin-bottom: 24px;
}

.social-links {
  display: flex;
  gap: 16px;
}

.social-links a {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background-color: rgba(255,255,255,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background-color 0.2s;
}

.social-links a:hover {
  background-color: var(--color-green);
  color: var(--color-black);
}

.footer-col h4 {
  color: var(--color-white);
  font-size: 16px;
  margin-bottom: 24px;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-col a {
  color: rgba(255,255,255,0.6);
  font-size: 14px;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--color-white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: rgba(255,255,255,0.5);
  font-size: 14px;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero h1 { font-size: 48px; }
  .features-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .feed-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .hero h1 { font-size: 40px; }
  .courses-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .stats-grid { gap: 24px; }
  .stat-item h3 { font-size: 40px; }
}

document.addEventListener('DOMContentLoaded', () => {
  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');

  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');

    question.addEventListener('click', () => {
      const isActive = item.classList.contains('active');

      // Close all items
      faqItems.forEach(faq => {
        faq.classList.remove('active');
        faq.querySelector('.faq-answer').style.maxHeight = null;
      });

      // If it wasn't active, open it
      if (!isActive) {
        item.classList.add('active');
        const answer = item.querySelector('.faq-answer');
        answer.style.maxHeight = answer.scrollHeight + 'px';
      }
    });
  });

  // Course Category Tabs Filtering
  const tabBtns = document.querySelectorAll('.tab-btn');
  const courseCards = document.querySelectorAll('.course-card');

  tabBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      // Remove active class from all tabs
      tabBtns.forEach(t => t.classList.remove('active'));
      // Add active class to clicked tab
      btn.classList.add('active');

      const category = btn.getAttribute('data-category');

      // Filter courses
      courseCards.forEach(card => {
        if (category === 'all' || card.getAttribute('data-category').includes(category)) {
          card.style.display = 'block';
        } else {
          card.style.display = 'none';
        }
      });
    });
  });

  // Hero Sign Up Buttons Interaction simulation
  const btnGoogle = document.querySelector('.btn-google');
  if (btnGoogle) {
    btnGoogle.addEventListener('click', (e) => {
      e.preventDefault();
      alert('Initiating OAuth sign-up flow with Google...');
    });
  }

  const btnEmail = document.querySelector('.btn-email');
  if (btnEmail) {
    btnEmail.addEventListener('click', (e) => {
      e.preventDefault();
      alert('Opening Email sign-up modal...');
    });
  }

  // Teacher Carousel Scroll indicators/affordance
  const teacherCarousel = document.querySelector('.teachers-carousel');
  if (teacherCarousel) {
    let isDown = false;
    let startX;
    let scrollLeft;

    teacherCarousel.addEventListener('mousedown', (e) => {
      isDown = true;
      startX = e.pageX - teacherCarousel.offsetLeft;
      scrollLeft = teacherCarousel.scrollLeft;
    });
    teacherCarousel.addEventListener('mouseleave', () => {
      isDown = false;
    });
    teacherCarousel.addEventListener('mouseup', () => {
      isDown = false;
    });
    teacherCarousel.addEventListener('mousemove', (e) => {
      if (!isDown) return;
      e.preventDefault();
      const x = e.pageX - teacherCarousel.offsetLeft;
      const walk = (x - startX) * 2; // Scroll-fast
      teacherCarousel.scrollLeft = scrollLeft - walk;
    });
  }
});
